"use strict";
const one=(selector,root=document)=>root.querySelector(selector),all=(selector,root=document)=>[...root.querySelectorAll(selector)];
const state=window.MarxiaUIState;
const defaultProducts=[{name:"Café Andino · 500 g",sku:"CAF-500",stock:8,price:12.5,color:"#8b5e3c",emoji:"☕"},{name:"Salsa de Mango",sku:"SAL-240",stock:17,price:6.75,color:"#e99b31",emoji:"🥭"},{name:"Tortillas Artesanales",sku:"TOR-012",stock:0,price:4.9,color:"#d6ad72",emoji:"🌮"}];
const cachedProducts=state.get("products",defaultProducts);const products=Array.isArray(cachedProducts)?cachedProducts:defaultProducts.map(x=>({...x}));
const saveProducts=()=>state.set("products",products);
const renderProducts=()=>{const host=one("#products");if(!host)return;host.innerHTML=products.map((p,index)=>`<div class="product"><i style="background:${p.color}">${p.emoji}</i><span><b>${p.name}</b><small>${p.sku} · ${p.price.toFixed(2)}</small></span><em class="${p.stock?'low':'out'}">${p.stock?p.stock+' '+tr("left"):tr("Out")}</em><button class="remove-item" data-remove-product="${index}" aria-label="${tr("Remove")} ${p.name}">×</button></div>`).join("");all("[data-remove-product]",host).forEach(button=>button.onclick=()=>{const item=products[Number(button.dataset.removeProduct)];if(confirm(tr("Remove this product from the catalog?"))){products.splice(Number(button.dataset.removeProduct),1);saveProducts();renderProducts()}})};
const modal=one("#modal"), form=one("#productForm"), photo=one("#photo"), upload=one("#upload"), taxToggle=one("#taxToggle"), taxValue=one("#taxValue"), stock=one("#stock");
const mobileSectionsToggle=one("#mobileSectionsToggle"),workspaceNavToggle=one("#workspaceNavToggle"),workspaceSections=one("#workspaceSections"),accountNavToggle=one("#accountNavToggle"),accountControls=one("#accountControls");
const workspaceToggles=[mobileSectionsToggle,workspaceNavToggle].filter(Boolean);
const setWorkspaceMenuState=open=>{if(!workspaceSections)return;workspaceSections.classList.toggle("nav-open",open);workspaceSections.classList.toggle("mobile-open",open);workspaceToggles.forEach(toggle=>{toggle.classList.toggle("open",open);toggle.setAttribute("aria-expanded",String(open))})};
const setAccountMenuState=open=>{if(!accountControls)return;accountControls.classList.toggle("nav-open",open);accountNavToggle?.classList.toggle("open",open);accountNavToggle?.setAttribute("aria-expanded",String(open))};
const closeMenu=()=>{setWorkspaceMenuState(false);setAccountMenuState(false)};
const toggleWorkspaceMenu=event=>{event?.stopPropagation();const open=!workspaceSections?.classList.contains("nav-open");setAccountMenuState(false);setWorkspaceMenuState(open)};
const toggleAccountMenu=event=>{event?.stopPropagation();const open=!accountControls?.classList.contains("nav-open");setWorkspaceMenuState(false);setAccountMenuState(open)};
workspaceToggles.forEach(toggle=>toggle.addEventListener("click",toggleWorkspaceMenu));
accountNavToggle?.addEventListener("click",toggleAccountMenu);
document.addEventListener("click",event=>{if(workspaceSections?.classList.contains("nav-open")&&!event.target.closest("#workspaceSections")&&!event.target.closest("#workspaceNavToggle")&&!event.target.closest("#mobileSectionsToggle"))setWorkspaceMenuState(false);if(accountControls?.classList.contains("nav-open")&&!event.target.closest("#accountControls")&&!event.target.closest("#accountNavToggle"))setAccountMenuState(false)});
one("#mobileSettings")?.addEventListener("click",()=>selectView("Settings"));
one("#mobileLanguage")?.addEventListener("click",()=>one("#languageToggle").click());
one("#mobileTheme")?.addEventListener("click",()=>one("#themeToggle").click());
one("#mobileSupport")?.addEventListener("click",()=>selectView("Support"));
