const localize=(root=document)=>{const translate=value=>{const lead=value.match(/^\s*/)[0],tail=value.match(/\s*$/)[0],clean=value.trim(),source=en[clean]||clean;return clean&&es[source]?lead+tr(source)+tail:value};const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())node.nodeValue=translate(node.nodeValue);const elements=root.nodeType===1?[root,...root.querySelectorAll("*")]:[...root.querySelectorAll("*")];elements.forEach(el=>["placeholder","aria-label","title","data-tooltip"].forEach(name=>{if(el.hasAttribute(name))el.setAttribute(name,translate(el.getAttribute(name)))}))};
