function wireOrderFilter(){
 const select=one("#ordersFilter"),rows=all("[data-order-status]",viewHost),status=one("#ordersFilterStatus"),empty=one("#ordersFilterEmpty");
 if(!select||!status||!empty)return;
 const update=()=>{
  const filter=select.value;
  let visible=0;
  rows.forEach(row=>{const show=filter==="all"||row.dataset.orderStatus===filter;row.hidden=!show;if(show)visible++});
  status.textContent=visible+" / "+rows.length+" "+tr("orders shown");
  empty.hidden=visible!==0
 };
 select.addEventListener("change",update);
 update()
}
